    /// <summary>
    /// Engine order. Default auto tries google, brave, bing, duckduckgo, yahoo, then baidu. A comma-separated list is followed as given. ddg and duck mean duckduckgo. Unknown names are ignored. Default: "auto".
    /// </summary>
    public string? Engines { get; init; }

    /// <summary>
    /// Country code. Defaults to us when omitted. For example us, fr, gb, de.
    /// </summary>
    public string? Gl { get; init; }

    /// <summary>
    /// Language code. Defaults to en when omitted. For example en, fr, de.
    /// </summary>
    public string? Hl { get; init; }

    /// <summary>
    /// Comma-separated list of fields to keep in the response, with dot notation for nested fields (e.g. name,location.city). Does not change the credit cost.
    /// </summary>
    public string? Fields { get; init; }

    /// <summary>
    /// Process the request asynchronously: the response is a job_id to poll on /v1/jobs/{id} (see waitForJob). Default: false.
    /// </summary>
    public bool? IsAsync { get; init; }

    /// <summary>
    /// Return HTTP 200 even when an error occurs; the error is then in the response body. Default: false.
    /// </summary>
    public bool? SoftFail { get; init; }

    /// <inheritdoc />
    public IEnumerable<KeyValuePair<string, object?>> ToWire()
    {
        yield return new("query", Query);
        yield return new("engines", Engines);
        yield return new("gl", Gl);
        yield return new("hl", Hl);
        yield return new("fields", Fields);
        yield return new("is_async", IsAsync);
        yield return new("soft_fail", SoftFail);
    }
}

